-- Run with Supabase CLI migrations. Never expose the service role key to the browser.
create extension if not exists pgcrypto;
create table public.profiles (id uuid primary key references auth.users(id) on delete cascade, nickname text not null default '探索者', bio text not null default '', timezone text not null default 'Asia/Shanghai', role text not null default 'member' check(role in ('member','admin')), created_at timestamptz not null default now());
create table public.interest_tags (id bigint generated always as identity primary key, name text not null unique, active boolean not null default true);
insert into public.interest_tags(name) values ('生活'),('摄影'),('设计'),('科技'),('游戏'),('情感'),('知识'),('艺术');
create table public.user_interests (user_id uuid not null references public.profiles(id) on delete cascade, tag_id bigint not null references public.interest_tags(id), primary key(user_id,tag_id));
create table public.posts (id uuid primary key default gen_random_uuid(), author_id uuid references public.profiles(id) on delete set null, tag_id bigint not null references public.interest_tags(id), title text not null check(length(title) between 1 and 80), body text not null check(length(body) between 1 and 5000), status text not null default 'published' check(status in ('draft','published','hidden')), is_demo boolean not null default false, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create index posts_feed_idx on public.posts(status,created_at desc);
create table public.post_media (id uuid primary key default gen_random_uuid(), post_id uuid not null references public.posts(id) on delete cascade, storage_path text not null unique, sort_order int not null default 0);
create table public.daily_decks (id uuid primary key default gen_random_uuid(), user_id uuid not null references public.profiles(id) on delete cascade, local_date date not null, timezone text not null, swapped_at timestamptz, created_at timestamptz not null default now(), unique(user_id,local_date));
create table public.daily_cards (deck_id uuid not null references public.daily_decks(id) on delete cascade, slot int not null check(slot between 1 and 5), post_id uuid not null references public.posts(id), opened_at timestamptz, primary key(deck_id,slot), unique(deck_id,post_id));
create table public.user_interactions (user_id uuid not null references public.profiles(id) on delete cascade, post_id uuid not null references public.posts(id) on delete cascade, viewed_at timestamptz, skipped_at timestamptz, rating int check(rating between 1 and 5), primary key(user_id,post_id));
create table public.bookmarks (user_id uuid not null references public.profiles(id) on delete cascade, post_id uuid not null references public.posts(id) on delete cascade, created_at timestamptz not null default now(), primary key(user_id,post_id));
create table public.comments (id uuid primary key default gen_random_uuid(), post_id uuid not null references public.posts(id) on delete cascade, author_id uuid not null references public.profiles(id) on delete cascade, parent_id uuid references public.comments(id) on delete set null, body text not null check(length(trim(body)) between 1 and 1000), status text not null default 'visible' check(status in ('visible','hidden')), created_at timestamptz not null default now());
create index comments_post_idx on public.comments(post_id,created_at desc);
create table public.comment_reactions (comment_id uuid not null references public.comments(id) on delete cascade, user_id uuid not null references public.profiles(id) on delete cascade, kind text not null check(kind in ('like','insightful')), primary key(comment_id,user_id,kind));
create table public.reports (id uuid primary key default gen_random_uuid(), reporter_id uuid not null references public.profiles(id) on delete cascade, comment_id uuid references public.comments(id) on delete cascade, post_id uuid references public.posts(id) on delete cascade, reason text not null check(length(trim(reason)) between 3 and 500), status text not null default 'open' check(status in ('open','resolved','dismissed')), created_at timestamptz not null default now(), check((comment_id is null) <> (post_id is null)));
create function public.is_admin() returns boolean language sql stable security definer set search_path=public as $$ select exists(select 1 from public.profiles where id=auth.uid() and role='admin') $$;
create function public.prevent_role_change() returns trigger language plpgsql as $$ begin if new.role<>old.role and not public.is_admin() then raise exception 'role change denied'; end if; return new; end $$;
create trigger profiles_role_guard before update on public.profiles for each row execute function public.prevent_role_change();
create function public.create_profile() returns trigger language plpgsql security definer set search_path=public as $$ begin insert into public.profiles(id) values(new.id); return new; end $$;
create trigger auth_profile after insert on auth.users for each row execute function public.create_profile();
alter table public.profiles enable row level security;
alter table public.interest_tags enable row level security;
alter table public.user_interests enable row level security;
alter table public.posts enable row level security;
alter table public.post_media enable row level security;
alter table public.daily_decks enable row level security;
alter table public.daily_cards enable row level security;
alter table public.user_interactions enable row level security;
alter table public.bookmarks enable row level security;
alter table public.comments enable row level security;
alter table public.comment_reactions enable row level security;
alter table public.reports enable row level security;
create policy profiles_read on public.profiles for select using(true);
create policy profiles_update on public.profiles for update using(id=auth.uid()) with check(id=auth.uid());
create policy tags_read on public.interest_tags for select using(active or public.is_admin());
create policy tags_admin on public.interest_tags for all using(public.is_admin()) with check(public.is_admin());
create policy interests_read on public.user_interests for select using(user_id=auth.uid());
create policy interests_write on public.user_interests for all using(user_id=auth.uid()) with check(user_id=auth.uid());
create policy posts_read on public.posts for select using(status='published' or author_id=auth.uid() or public.is_admin());
create policy posts_insert on public.posts for insert with check(author_id=auth.uid() and not is_demo and status in ('draft','published'));
create policy posts_update on public.posts for update using(author_id=auth.uid() or public.is_admin()) with check(author_id=auth.uid() or public.is_admin());
create policy posts_delete on public.posts for delete using(author_id=auth.uid() or public.is_admin());
create policy media_read on public.post_media for select using(exists(select 1 from public.posts p where p.id=post_id and (p.status='published' or p.author_id=auth.uid() or public.is_admin())));
create policy media_write on public.post_media for all using(exists(select 1 from public.posts p where p.id=post_id and p.author_id=auth.uid())) with check(exists(select 1 from public.posts p where p.id=post_id and p.author_id=auth.uid()));
create policy decks_read on public.daily_decks for select using(user_id=auth.uid());
create policy cards_read on public.daily_cards for select using(exists(select 1 from public.daily_decks d where d.id=deck_id and d.user_id=auth.uid()));
create policy interactions_own on public.user_interactions for all using(user_id=auth.uid()) with check(user_id=auth.uid());
create policy bookmarks_own on public.bookmarks for all using(user_id=auth.uid()) with check(user_id=auth.uid());
create policy comments_read on public.comments for select using(status='visible' or author_id=auth.uid() or public.is_admin());
create policy comments_insert on public.comments for insert with check(author_id=auth.uid() and status='visible');
create policy comments_delete on public.comments for delete using(author_id=auth.uid() or public.is_admin());
create policy comments_admin on public.comments for update using(public.is_admin()) with check(public.is_admin());
create policy reactions_read on public.comment_reactions for select using(true);
create policy reactions_own on public.comment_reactions for all using(user_id=auth.uid()) with check(user_id=auth.uid());
create policy reports_insert on public.reports for insert with check(reporter_id=auth.uid() and status='open');
create policy reports_read on public.reports for select using(reporter_id=auth.uid() or public.is_admin());
create policy reports_admin on public.reports for update using(public.is_admin()) with check(public.is_admin());
